    field_policy_version character varying(100) NOT NULL,
    index_storage_ref text,
    content_hash character varying(100),
    generated_at timestamp with time zone,
    published_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    showcase_case_set_id character varying(100),
    showcase_case_set_version integer,
    CONSTRAINT publication_status_valid CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'VALIDATED'::character varying, 'PUBLISHED'::character varying, 'REJECTED'::character varying])::text[]))),
    CONSTRAINT publication_version_positive CHECK ((version > 0))
);


ALTER TABLE touchstone.publications OWNER TO touchstone;

