);


ALTER TABLE touchstone.run_artifacts OWNER TO touchstone;

--
-- Name: run_batches; Type: TABLE; Schema: touchstone; Owner: touchstone
--

CREATE TABLE touchstone.run_batches (
    id uuid NOT NULL,
    name character varying(200) NOT NULL,
    experiment_type character varying(50) NOT NULL,
    fixed_conditions jsonb NOT NULL,
    status character varying(30) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    experiment_variable character varying(30),
    requested_repetitions integer DEFAULT 1 NOT NULL,
    random_seed bigint,
    created_by character varying(200),
    idempotency_key character varying(200),
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    template_id character varying(100),
    template_version integer,
    experiment_definition_version character varying(50),
    fixed_conditions_hash character varying(64),
    CONSTRAINT run_batch_experiment_variable_valid CHECK (((experiment_variable IS NULL) OR ((experiment_variable)::text = ANY ((ARRAY['AGENT_IMPLEMENTATION'::character varying, 'CONTEXT_STRATEGY'::character varying])::text[])))),
    CONSTRAINT run_batch_repetitions_positive CHECK ((requested_repetitions > 0)),
    CONSTRAINT run_batch_template_version_valid CHECK ((((template_id IS NULL) AND (template_version IS NULL)) OR ((template_id IS NOT NULL) AND (template_version IS NOT NULL) AND (template_version > 0))))
);


ALTER TABLE touchstone.run_batches OWNER TO touchstone;

--
-- Name: COLUMN run_batches.requested_repetitions; Type: COMMENT; Schema: touchstone; Owner: touchstone
--

COMMENT ON COLUMN touchstone.run_batches.requested_repetitions IS 'repeat_count(重复运行次数)的数据库层列名;对比用例只允许 3/5,压缩用例每格固定 1';


--
-- Name: COLUMN run_batches.template_id; Type: COMMENT; Schema: touchstone; Owner: touchstone
--

COMMENT ON COLUMN touchstone.run_batches.template_id IS '实验模板标识(代码常量单一真源,如 governance-on-off);NULL=2026-08-26 前的旧实验定义批次';


--
-- Name: COLUMN run_batches.template_version; Type: COMMENT; Schema: touchstone; Owner: touchstone
--

COMMENT ON COLUMN touchstone.run_batches.template_version IS '实验模板版本;与 template_id 同为 NULL 或同非 NULL';


--
-- Name: COLUMN run_batches.experiment_definition_version; Type: COMMENT; Schema: touchstone; Owner: touchstone
--

COMMENT ON COLUMN touchstone.run_batches.experiment_definition_version IS '实验定义口径版本(run-config-v2);用于区分旧 agent_mode 对照与新模板单变量实验';


--
-- Name: COLUMN run_batches.fixed_conditions_hash; Type: COMMENT; Schema: touchstone; Owner: touchstone
--

COMMENT ON COLUMN touchstone.run_batches.fixed_conditions_hash IS '批次固定条件的规范化哈希(键排序+紧凑JSON 的 SHA-256,引擎计算);变体只能改变声明的主自变量';


