--
-- Name: run_measurements; Type: TABLE; Schema: touchstone; Owner: touchstone
--

CREATE TABLE touchstone.run_measurements (
    run_id uuid NOT NULL,
    queue_ms bigint DEFAULT 0 NOT NULL,
    snapshot_ms bigint DEFAULT 0 NOT NULL,
    context_collect_ms bigint DEFAULT 0 NOT NULL,
    context_compress_ms bigint DEFAULT 0 NOT NULL,
    tool_loading_ms bigint DEFAULT 0 NOT NULL,
    llm_ms bigint DEFAULT 0 NOT NULL,
    tool_ms bigint DEFAULT 0 NOT NULL,
    guardrail_ms bigint DEFAULT 0 NOT NULL,
    judgment_ms bigint DEFAULT 0 NOT NULL,
    first_output_ms bigint,
    total_duration_ms bigint NOT NULL,
    prompt_tokens integer DEFAULT 0 NOT NULL,
    cached_prompt_tokens integer DEFAULT 0 NOT NULL,
    completion_tokens integer DEFAULT 0 NOT NULL,
    compression_input_tokens integer DEFAULT 0 NOT NULL,
    compression_output_tokens integer DEFAULT 0 NOT NULL,
    estimated_model_cost numeric(18,8),
    estimated_compression_cost numeric(18,8),
    currency character varying(10),
    pricing_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT run_measurement_numbers_valid CHECK (((queue_ms >= 0) AND (snapshot_ms >= 0) AND (context_collect_ms >= 0) AND (context_compress_ms >= 0) AND (tool_loading_ms >= 0) AND (llm_ms >= 0) AND (tool_ms >= 0) AND (guardrail_ms >= 0) AND (judgment_ms >= 0) AND ((first_output_ms IS NULL) OR (first_output_ms >= 0)) AND (total_duration_ms >= 0) AND (prompt_tokens >= 0) AND (cached_prompt_tokens >= 0) AND (completion_tokens >= 0) AND (compression_input_tokens >= 0) AND (compression_output_tokens >= 0) AND ((estimated_model_cost IS NULL) OR (estimated_model_cost >= (0)::numeric)) AND ((estimated_compression_cost IS NULL) OR (estimated_compression_cost >= (0)::numeric))))
);


ALTER TABLE touchstone.run_measurements OWNER TO touchstone;

