    CONSTRAINT showcase_item_fields_valid CHECK (((((item_type)::text = 'COMPARISON_CASE_REF'::text) AND (case_id IS NOT NULL) AND (case_version IS NOT NULL) AND (session_id IS NULL)) OR (((item_type)::text = 'COMPRESSION_SESSION_REF'::text) AND (session_id IS NOT NULL) AND (session_version IS NOT NULL) AND (case_id IS NULL)))),
    CONSTRAINT showcase_item_type_valid CHECK (((item_type)::text = ANY ((ARRAY['COMPARISON_CASE_REF'::character varying, 'COMPRESSION_SESSION_REF'::character varying])::text[])))
);


