    error text,
    CONSTRAINT test_job_unit_repeat_valid CHECK ((repeat_index >= 0)),
    CONSTRAINT test_job_unit_status_valid CHECK (((status)::text = ANY ((ARRAY['QUEUED'::character varying, 'RUNNING'::character varying, 'COMPLETE'::character varying, 'CANCELLED'::character varying, 'INTERRUPTED'::character varying, 'FAILED'::character varying])::text[])))
);


ALTER TABLE touchstone.test_job_units OWNER TO postgres;

--
-- Name: test_jobs; Type: TABLE; Schema: touchstone; Owner: postgres
--

CREATE TABLE touchstone.test_jobs (
    id character varying(50) NOT NULL,
    requester_type character varying(20) NOT NULL,
    anonymous_id_hash character varying(100),
    run_purpose character varying(30) NOT NULL,
    test_type character varying(30) NOT NULL,
    execution_scope character varying(30) NOT NULL,
    status character varying(20) NOT NULL,
    target_type character varying(10) NOT NULL,
    case_id character varying(100),
    case_version integer,
    session_id character varying(100),
    session_version integer,
    current_event_id character varying(100),
    current_message_hash character varying(100),
    context_variant character varying(50),
    agent_mode_id character varying(50),
    context_artifact_id character varying(100),
    context_artifact_hash character varying(100),
    parent_job_id character varying(50),
    repeat_count integer NOT NULL,
    max_agent_steps integer NOT NULL,
    requested_tool_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    custom_conditions boolean DEFAULT false NOT NULL,
    publishable boolean DEFAULT false NOT NULL,
    tool_catalog_version character varying(100),
    fixture_set_id character varying(100),
    quota_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    idempotency_key character varying(200),
    cancel_requested boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    error text,
    template_id character varying(100),
    template_version integer,
    CONSTRAINT test_job_anonymous_not_publishable CHECK ((((requester_type)::text <> 'ANONYMOUS'::text) OR (publishable = false))),
    CONSTRAINT test_job_purpose_valid CHECK (((run_purpose)::text = ANY ((ARRAY['PUBLIC_TRIAL'::character varying, 'OWNER_EXPERIMENT'::character varying, 'SYSTEM_REGRESSION'::character varying])::text[]))),
    CONSTRAINT test_job_repeat_count_valid CHECK (((((test_type)::text = 'COMPARISON_CASE'::text) AND (repeat_count = ANY (ARRAY[3, 5]))) OR (((test_type)::text = 'COMPRESSION_CASE'::text) AND (repeat_count = 1)))),
    CONSTRAINT test_job_requester_valid CHECK (((requester_type)::text = ANY ((ARRAY['ANONYMOUS'::character varying, 'OWNER'::character varying, 'SYSTEM'::character varying])::text[]))),
    CONSTRAINT test_job_scope_valid CHECK (((execution_scope)::text = ANY ((ARRAY['comparison-full'::character varying, 'context-only'::character varying, 'current-combo'::character varying, 'full-matrix'::character varying, 'native-matrix'::character varying])::text[]))),
    CONSTRAINT test_job_status_valid CHECK (((status)::text = ANY ((ARRAY['QUEUED'::character varying, 'RUNNING'::character varying, 'COMPLETE'::character varying, 'FAILED'::character varying, 'CANCELLED'::character varying, 'INTERRUPTED'::character varying, 'PARTIAL'::character varying])::text[]))),
    CONSTRAINT test_job_steps_valid CHECK ((max_agent_steps > 0)),
    CONSTRAINT test_job_target_fields_valid CHECK (((((target_type)::text = 'CASE'::text) AND (case_id IS NOT NULL) AND (case_version IS NOT NULL) AND (session_id IS NULL)) OR (((target_type)::text = 'SESSION'::text) AND (session_id IS NOT NULL) AND ((session_id)::text <> ''::text) AND (case_id IS NULL)))),
    CONSTRAINT test_job_target_valid CHECK (((target_type)::text = ANY ((ARRAY['CASE'::character varying, 'SESSION'::character varying])::text[]))),
    CONSTRAINT test_job_type_valid CHECK (((test_type)::text = ANY ((ARRAY['COMPRESSION_CASE'::character varying, 'COMPARISON_CASE'::character varying])::text[])))
);


ALTER TABLE touchstone.test_jobs OWNER TO postgres;

