    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tool_call_numbers_valid CHECK (((sequence >= 0) AND (duration_ms >= 0))),
    CONSTRAINT tool_call_status_valid CHECK (((status)::text = ANY ((ARRAY['SUCCESS'::character varying, 'FAILED'::character varying, 'TIMEOUT'::character varying, 'DENIED'::character varying, 'INVALID'::character varying])::text[])))
);


