    enabled boolean DEFAULT true NOT NULL,
    operations jsonb DEFAULT '[]'::jsonb NOT NULL,
    toolsets jsonb DEFAULT '[]'::jsonb NOT NULL,
    side_effect character varying(20) DEFAULT 'none'::character varying NOT NULL,
    requires_confirmation boolean DEFAULT false NOT NULL,
    risk_level character varying(10) DEFAULT 'low'::character varying NOT NULL,
    CONSTRAINT tool_capability_adapter_valid CHECK (((adapter)::text = ANY ((ARRAY['mcp'::character varying, 'java'::character varying, 'web'::character varying, 'local'::character varying])::text[]))),
    CONSTRAINT tool_capability_risk_valid CHECK (((risk_level)::text = ANY ((ARRAY['low'::character varying, 'medium'::character varying, 'high'::character varying])::text[]))),
    CONSTRAINT tool_capability_side_effect_valid CHECK (((side_effect)::text = ANY ((ARRAY['none'::character varying, 'write'::character varying, 'external_action'::character varying])::text[]))),
    CONSTRAINT tool_capability_timeout_valid CHECK ((timeout_seconds > 0))
);


