    status character varying(20) DEFAULT 'GRANTED'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    consumed_at timestamp with time zone,
    CONSTRAINT write_confirmation_binding_valid CHECK (((((status)::text = 'USED'::text) AND (consumed_at IS NOT NULL)) OR (((status)::text = ANY ((ARRAY['GRANTED'::character varying, 'REVOKED'::character varying])::text[])) AND (consumed_at IS NULL)))),
    CONSTRAINT write_confirmation_status_valid CHECK (((status)::text = ANY ((ARRAY['GRANTED'::character varying, 'USED'::character varying, 'REVOKED'::character varying])::text[])))
);


ALTER TABLE touchstone.write_confirmations OWNER TO postgres;

--
-- Name: TABLE write_confirmations; Type: COMMENT; Schema: touchstone; Owner: postgres
